describe('Background Job Notification', () => {
    beforeEach(() => {
        cy.visit('/'); // Adjust the URL to your application's homepage
    });

    it('should display a toast notification when the background job completes successfully', () => {
        // Trigger the background job
        cy.get('#start-job-button').click(); // Adjust the selector to your start job button

        // Wait for the job to complete (this may vary based on your implementation)
        cy.wait(5000); // Adjust the wait time as necessary

        // Assert that the toast notification is visible
        cy.get('.toast-notification') // Adjust the selector to your toast notification
            .should('be.visible')
            .and('contain', 'Job completed successfully!'); // Adjust the message as necessary
    });

    it('should not display a toast notification if the job fails', () => {
        // Trigger the background job that is expected to fail
        cy.get('#start-failing-job-button').click(); // Adjust the selector to your start failing job button

        // Wait for the job to complete
        cy.wait(5000); // Adjust the wait time as necessary

        // Assert that the toast notification is not visible
        cy.get('.toast-notification') // Adjust the selector to your toast notification
            .should('not.exist');
    });
});
